class LSMTree:
    def __init__(self, memtable_threshold: int = 3):
        self.threshold = memtable_threshold
        self.memtable = {}
        self.sstables: list[dict] = []

    def put(self, key: str, value: str) -> None:
        self.memtable[key] = value
        if len(self.memtable) >= self.threshold:
            self.sstables.insert(0, dict(self.memtable))
            self.memtable.clear()

    def get(self, key: str) -> str | None:
        if key in self.memtable:
            val = self.memtable[key]
            return None if val == '__DELETED__' else val
        for sst in self.sstables:
            if key in sst:
                val = sst[key]
                return None if val == '__DELETED__' else val
        return None

    def delete(self, key: str) -> None:
        self.put(key, '__DELETED__')
